cypress_script:
describe('Multi-Level Dropdown Navigation Menu', () => {
  it('should display submenu items when Enabled is clicked', () => {
    cy.visit('https://the-internet.herokuapp.com/jqueryui/menu');
    cy.get('a:contains("Enabled")').click();
    cy.get('li#ui-id-4').should('be.visible');
    cy.get('li#ui-id-5').should('be.visible');
    cy.get('li#ui-id-6').should('be.visible');
    cy.get('li#ui-id-7').should('be.visible');
    cy.get('li#ui-id-8').should('be.visible');
  });

  it('should not allow interaction with Disabled item', () => {
    cy.visit('https://the-internet.herokuapp.com/jqueryui/menu');
    cy.get('li#ui-id-1').should('be.visible');
    cy.get('li#ui-id-1').click({ force: true });
    cy.url().should('eq', 'https://the-internet.herokuapp.com/jqueryui/menu');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Multi-Level Dropdown Navigation Menu', () => {
  test('should display submenu items when Enabled is clicked', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/jqueryui/menu');
    await page.click('a:has-text("Enabled")');
    await expect(page.locator('li#ui-id-4')).toBeVisible();
    await expect(page.locator('li#ui-id-5')).toBeVisible();
    await expect(page.locator('li#ui-id-6')).toBeVisible();
    await expect(page.locator('li#ui-id-7')).toBeVisible();
    await expect(page.locator('li#ui-id-8')).toBeVisible();
  });

  test('should not allow interaction with Disabled item', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/jqueryui/menu');
    await expect(page.locator('li#ui-id-1')).toBeVisible();
    await page.click('li#ui-id-1');
    await expect(page.url()).toBe('https://the-internet.herokuapp.com/jqueryui/menu');
  });
});
